  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Customer's primary key. {@link shopping_mall_customers.id}.
  shopping_mall_customer_id String @db.Uuid

  /// Timestamp when the wishlist was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the wishlist was last modified (items added/removed).
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp. If null, wishlist is active. If set, wishlist is
  /// marked for deletion but record preserved for audit.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer shopping_mall_customers @relation(fields: [shopping_mall_customer_id], references: [id], onDelete: Cascade)

