  shopping_mall_product_variant_id String @db.Uuid

  /// Timestamp when this wishlist item was added to the wishlist.
  created_at DateTime @db.Timestamptz

  /// Timestamp when this wishlist item was last modified (reordered or moved).
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp. If null, item is in wishlist. If set, item has
