  // spellchecker: ignore-next-line
  @@unique([shopping_mall_wishlist_id, shopping_mall_product_variant_id], map: "shopping_mall_wishlist_items_shopping_mall_wishlist_id_e2467ce3")
  // spellchecker: ignore-next-line
  @@index([shopping_mall_wishlist_id, created_at], map: "shopping_mall_wishlist_items_shopping_mall_wishlist_id_57e5e679")
  // spellchecker: ignore-next-line
  @@index([shopping_mall_product_variant_id, created_at], map: "shopping_mall_wishlist_items_shopping_mall_product_var_6de79db4")
  // spellchecker: ignore-next-line
  @@index([shopping_mall_wishlist_id, deleted_at], map: "shopping_mall_wishlist_items_shopping_mall_wishlist_id_1cf3d84c")
