  // spellchecker: ignore-next-line
  administrator shopping_mall_administrators? @relation(fields: [shopping_mall_administrator_id], references: [id], onDelete: Cascade, map: "shopping_mall_review_moderation_logs_shopping_mall_adm_6616e518")
  // spellchecker: ignore-next-line
  report        shopping_mall_review_reports? @relation(fields: [shopping_mall_review_report_id], references: [id], onDelete: Cascade, map: "shopping_mall_review_moderation_logs_shopping_mall_rev_1c5a0dec")

  // spellchecker: ignore-next-line
  @@index([shopping_mall_administrator_id], map: "shopping_mall_review_moderation_logs_shopping_mall_adm_de8b1ba2")
  // spellchecker: ignore-next-line
  @@index([shopping_mall_review_report_id], map: "shopping_mall_review_moderation_logs_shopping_mall_rev_44c6fbb4")
