  @@index([shopping_mall_product_review_id])
  @@index([created_at])
  @@index([edit_number])
  @@index([title_before(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([title_after(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body_before(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body_after(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-09-sellers.prisma:
/// Seller application records submitted by new business entities seeking to
/// join the marketplace.
///
/// Tracks the complete lifecycle of seller registration, from initial
/// application submission through admin review and approval/rejection.
/// Applications must be approved before sellers can list products or access
/// financial systems. Each application links to corresponding verification
/// documents and creates a seller profile upon approval.
///
/// Integration with identity services for independent authentication.
/// Applications maintain audit trails with timestamps and admin review
/// history. Soft deletion preserves data for compliance while allowing
/// administrative cleanup.
///
/// @namespace Sellers
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_seller_applications {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Applying customer's {@link shopping_mall_customers.id}.
  shopping_mall_customer_id String @db.Uuid

  /// Legal business name as registered with government authorities.
  business_name String

  /// Government-issued tax identification number for business validation.
  tax_id String

  /// Current status of the application: pending_review, approved, rejected.
  application_status String

  /// Admin-provided reason for application rejection. Required when status is
  /// 'rejected'.
  rejection_reason String?

  /// Timestamp when the application was submitted.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the application status was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the application was soft-deleted by admin action.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  // spellchecker: ignore-next-line
  customer shopping_mall_customers @relation(fields: [shopping_mall_customer_id], references: [id], onDelete: Cascade, map: "shopping_mall_seller_applications_shopping_mall_custom_9154a24f")

  shopping_mall_seller_verification_documents shopping_mall_seller_verification_documents[]

  @@index([shopping_mall_customer_id])
  @@index([application_status])
  @@index([created_at])
  @@index([business_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Documents submitted by sellers to verify their business identity and
/// legitimacy.
///
/// Contains scanned copies of government-issued documents including business
/// license, tax documentation, and bank account verification. Each document
/// is linked to a seller application and must be approved before seller
/// account activation. Documents are stored securely with encrypted access
/// controls.
///
/// The document upload process is managed through the seller application
/// workflow. All documents have an expiration date and require periodic
/// re-verification. Documents are only accessible to approved admin staff
/// and are archived when the seller account is terminated.
///
/// @namespace Sellers
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_seller_verification_documents {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Associated seller application {@link
  /// shopping_mall_seller_applications.id}.
  shopping_mall_seller_application_id String @db.Uuid

  /// Type of document: business_license, tax_certificate, bank_statement,
  /// government_id.
  document_type String

  /// Secure URL to the uploaded document file in object storage.
  document_url String @db.VarChar(80000)

  /// Original filename uploaded by the seller.
  document_name String

  /// Expiry date of the document when re-verification will be required.
  document_expires_at DateTime? @db.Timestamptz

  /// Admin user who reviewed and approved the document {@link
  /// shopping_mall_administrators.id}.
  verified_by String? @db.Uuid

  /// Timestamp when the document was verified by an admin.
  verified_at DateTime? @db.Timestamptz

  /// Timestamp when the document was uploaded.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the document metadata was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the document was soft-deleted by admin action.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  // spellchecker: ignore-next-line
  application shopping_mall_seller_applications @relation(fields: [shopping_mall_seller_application_id], references: [id], onDelete: Cascade, map: "shopping_mall_seller_verification_documents_shopping_m_df41f132")

  // spellchecker: ignore-next-line
  @@unique([shopping_mall_seller_application_id, document_type], map: "shopping_mall_seller_verification_documents_shopping_m_67b4e627")
  // spellchecker: ignore-next-line
  @@index([shopping_mall_seller_application_id], map: "shopping_mall_seller_verification_documents_shopping_m_b01588a9")
  @@index([document_type])
  @@index([verified_at])
  // spellchecker: ignore-next-line
  @@index([document_expires_at], map: "shopping_mall_seller_verification_documents_document_e_32b4d15c")
  @@index([document_name(ops: raw("gin_trgm_ops"))], type: Gin)
