  shopping_mall_seller_profile_id String @db.Uuid

  /// Name of the financial institution holding the account.
  bank_name String

  /// Last four digits of the bank account for user identification.
  account_number_last_four String

  /// Bank routing number for domestic transfers.
  routing_number String

  /// Type of account: checking, savings, business.
  account_type String

